command:
for f in pause-menu level-complete game-over rotate-prompt; do for w in 960 800; do if [ $w = 960 ]; then h=540; else h=450; fi; echo "=== $f @ ${w}x${h} ==="; bun .beegame/delivery/check-content.mjs --layout-draft content/ui/$f.json $w $h 2>&1 | python3 -c "
import json,sys
raw=sys.stdin.read()
try:
    d=json.loads(raw)
    if 'ok' in d: print(json.dumps({'ok':d['ok'],'diag':d['diagnostics']},ensure_ascii=False))
    else: print(raw[:400])
except Exception: print(raw[:400])
"; done; done

